with open('assets/flac_rt.flac', 'rb') as f:
    data = f.read()

class BitReader:
    def __init__(self, data, pos=0):
        self.data = data
        self.byte_pos = pos
        self.bit_pos = 0

    def read_bit(self):
        if self.byte_pos >= len(self.data):
            return 0
        b = (self.data[self.byte_pos] >> (7 - self.bit_pos)) & 1
        self.bit_pos += 1
        if self.bit_pos == 8:
            self.bit_pos = 0
            self.byte_pos += 1
        return b

    def read_bits(self, n):
        v = 0
        for _ in range(n):
            v = (v << 1) | self.read_bit()
        return v

    def read_signed_bits(self, n):
        v = self.read_bits(n)
        if v & (1 << (n - 1)):
            v -= (1 << n)
        return v

    def read_unary(self):
        v = 0
        while self.read_bit() == 0:
            v += 1
        return v

    def align(self):
        if self.bit_pos != 0:
            self.bit_pos = 0
            self.byte_pos += 1

br = BitReader(data, 8286) # frame start

def read_utf8(br):
    val = br.read_bits(8)
    if (val & 0x80) == 0:
        return val
    elif (val & 0xE0) == 0xC0:
        return ((val & 0x1F) << 6) | (br.read_bits(8) & 0x3F)
    elif (val & 0xF0) == 0xE0:
        return ((val & 0x0F) << 12) | ((br.read_bits(8) & 0x3F) << 6) | (br.read_bits(8) & 0x3F)
    elif (val & 0xF8) == 0xF0:
        return ((val & 0x07) << 18) | ((br.read_bits(8) & 0x3F) << 12) | ((br.read_bits(8) & 0x3F) << 6) | (br.read_bits(8) & 0x3F)
    return val

sync = br.read_bits(14)
strategy = br.read_bit()
bs_code = br.read_bits(4)
sr_code = br.read_bits(4)
ch_code = br.read_bits(4)
bps_code = br.read_bits(3)
br.read_bit() # reserved
fnum = read_utf8(br)

print(f'bs_code: {bs_code}, sr_code: {sr_code}')

if bs_code == 6: blocksize = br.read_bits(8) + 1
elif bs_code == 7: blocksize = br.read_bits(16) + 1
else: blocksize = 4096

if sr_code == 12: sr = br.read_bits(8)
elif sr_code in (13, 14): sr = br.read_bits(16)

crc8 = br.read_bits(8)
print(f'Actual blocksize: {blocksize}, sr_extra: {sr}, crc8: {crc8}')
""}

